/* 栞 / Shiori — the renderer has no filesystem or process access. */
const api=window.shiori;
const $=(s,r=document)=>r.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={
  book:'M4 4h6a3 3 0 0 1 3 3v14a4 4 0 0 0-4-3H4V4Zm16 0h-4a3 3 0 0 0-3 3v14a4 4 0 0 1 4-3h3V4Z',
  grid:'M3 3h7v7H3zM14 3h7v7h-7zM3 14h7v7H3zM14 14h7v7h-7z',
  clock:'M12 8v5l3 2M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0Z',
  tag:'M20 13 12 21 3 12V3h9l8 8a1.4 1.4 0 0 1 0 2ZM7 7h.01',
  settings:'M9 3h6l1 3 3 1 2 5-2 3-1 3-5 2-3-2-3-1-2-5 2-3 1-3 1-3ZM15 12a3 3 0 1 1-6 0 3 3 0 0 1 6 0Z',
  search:'m21 21-5-5M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0Z',
  plus:'M12 5v14M5 12h14',close:'m6 6 12 12M6 18 18 6',minus:'M5 12h14',square:'M5 5h14v14H5z',
  heart:'M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8Z',
  play:'m8 5 11 7-11 7V5Z',pause:'M8 5v14M16 5v14',stop:'M6 6h12v12H6z',
  refresh:'M20 7v5h-5M4 17v-5h5M5.5 7a8 8 0 0 1 13.2-2L20 7M4 17l1.3 2a8 8 0 0 0 13.2-2',
  folder:'M3 7V4h6l3 3h9v13H3V7Z',external:'M14 3h7v7M21 3 10 14M10 3H3v18h18v-7',
  filter:'M4 5h16M7 12h10M10 19h4M8 3v4M16 10v4M12 17v4',list:'M8 5h13M8 12h13M8 19h13M3 5h.01M3 12h.01M3 19h.01',
  star:'m12 3 3 6 6 1-4.5 4.5 1 6.5-5.5-3-5.5 3 1-6.5L3 10l6-1 3-6Z',
  chevron:'m9 5 7 7-7 7',check:'m5 12 4 4L19 6',download:'M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5',
  sparkles:'m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5L12 3Z',edit:'m16 3 5 5-12 12-6 1 1-6L16 3ZM13 6l5 5',
  chart:'M4 20V10M12 20V4M20 20v-7',leaf:'M20 3C8 2 2 8 5 16s15 3 15-13ZM5 20l9-10',info:'M12 11v6M12 7h.01M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0Z'
};
const icon=(name,cls='')=>`<svg class="${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.book}"/></svg>`;
const statuses={unplayed:'未开始',playing:'游玩中',completed:'已通关',onhold:'暂时搁置',dropped:'已放下'};
const heroGreetings={continue:[
 '故事还在继续，<br>回到那个世界吧。','书签仍在，<br>等你翻开下一页。','那些没说完的话，<br>还在等你。','熟悉的旋律响起，<br>接上昨天的故事。','再见一面吧，<br>在喜欢的世界里。','把日常暂存，<br>继续你的篇章。','书签已留好，<br>从这里继续。','离开的那一幕，<br>还为你留着位置。','今天的下一页，<br>想和谁一起翻开？','有些故事，<br>值得慢慢走下去。'
],discover:[
 '下一页，<br>会是什么样的故事？','新的相遇，<br>藏在哪张封面里？','留一点时间，<br>给未读的世界。','翻开一本，<br>从初次见面开始。','今天的故事，<br>就从这里开始吧。','也许这一页，<br>会成为新的偏爱。','把喜欢的故事，<br>一部部收藏起来。','书架上的世界，<br>总有一个在等你。','从一句问候，<br>走进另一种日常。','选一个封面，<br>赴一场新的约定。'
]};
function nextHeroGreeting(kind,previous){const count=heroGreetings[kind].length;if(previous===undefined){previous=-1;try{previous=Number(localStorage.getItem('shiori.hero.'+kind)??-1);}catch{}}let choice=previous>=0&&previous<count?Math.floor(Math.random()*(count-1)):Math.floor(Math.random()*count);if(choice>=previous&&previous>=0&&previous<count)choice++;try{localStorage.setItem('shiori.hero.'+kind,String(choice));}catch{}return choice;}
const heroGreetingChoice={continue:nextHeroGreeting('continue'),discover:nextHeroGreeting('discover')};
const heroGreeting=recent=>heroGreetings[recent?'continue':'discover'][heroGreetingChoice[recent?'continue':'discover']];

let selectionMode=false,selectedGames=new Set();
let managingWriters=false,writerSelection=new Set(),writerSearch='';
let data,view='library',query='',tab='all',sort='added',filters=[],filterMode='and',listMode=false,showAllCompanies=false,showAllSeries=false,showAllWriters=false,selectedId=null,editing=false,matchingId=null,matchQuery='',matchResults=null,matchProvider='all',matchWarnings=[],toastTimer,refreshing=false;

const tagKinds=[['companies','会社','STUDIOS'],['series','系列','SERIES'],['writers','脚本家','WRITERS'],['genres','作品标签','STORY TAGS'],['folders','原有目录','FOLDERS'],['custom','自定义','MY TAGS']];
let tagType='companies',tagQuery='',sidebarDraft=null;const sidebarExpanded=new Set();
function companyLabel(value){const key=s=>s.normalize('NFKC').toLowerCase().replace(/\s+/g,'');const entities=(data.companyEntities||[]).filter(e=>[e.name,...e.aliases].some(alias=>key(alias)===key(value)));const names=[...new Set(entities.map(e=>e.name))];return names.length===1?names[0]:value;}
function ensureSidebarDraft(){if(!sidebarDraft)sidebarDraft=Object.fromEntries(tagKinds.map(([type])=>[type,new Set(data.settings.sidebarTags?.[type]||[])]));const key=s=>s.normalize('NFKC').toLowerCase().replace(/\s+/g,'');sidebarDraft.companies=new Set([...sidebarDraft.companies].map(value=>{const entities=(data.companyEntities||[]).filter(e=>[e.name,...e.aliases].some(alias=>key(alias)===key(value)));const names=[...new Set(entities.map(e=>e.name))];return names.length===1?names[0]:value;}));}
function tagEntries(type){return counts(type).map(([name,count])=>{const games=visibleGames().filter(g=>g.tags[type]?.includes(name));const entity=type==='companies'?data.companyEntities?.find(e=>e.name===name):null;const author=type==='writers'?data.authors?.find(e=>e.name===name):null;const aliases=[...new Set(entity?.aliases||author?.aliases||[])].filter(a=>a!==name);const sources=[...new Set(games.map(g=>type==='companies'?g.companyTagSources?.[name]?.source||g.companySource?.source||'目录推测':type==='writers'?'制作人员署名':type==='genres'?(g.bangumiCompanyCredits?'Bangumi':g.metadata?.source||'作品资料'):type==='folders'?'本地目录':type==='custom'?'手动添加':'系列分类'))];return {name,count,games,entity,aliases,sources};});}
function matchedTags(){const q=tagQuery.normalize('NFKC').toLowerCase().replace(/\s+/g,'');return tagEntries(tagType).filter(t=>!q||[t.name,...t.aliases].some(a=>a.normalize('NFKC').toLowerCase().replace(/\s+/g,'').includes(q)));}
function sidebarSelectedCount(){ensureSidebarDraft();return Object.values(sidebarDraft).reduce((n,s)=>n+s.size,0);}
function tagCatalog(){ensureSidebarDraft();return matchedTags().map(t=>`<article class="tag-entry"><div class="tag-entry-top"><label class="pin-tag"><input type="checkbox" data-sidebar-type="${tagType}" data-sidebar-value="${esc(t.name)}" ${sidebarDraft[tagType].has(t.name)?'checked':''} aria-label="固定到侧栏：${esc(t.name)}"><span>固定</span></label><button class="tag-entry-name" data-action="filter" data-type="${tagType}" data-value="${esc(t.name)}">${esc(t.name)}</button><b>${t.count} 部</b></div><p class="tag-source">${t.sources.map(esc).join(' · ')}</p>${t.aliases.length?`<p class="tag-aliases">别名：${t.aliases.slice(0,5).map(esc).join(' / ')}${t.aliases.length>5?' …':''}</p>`:''}<details><summary>关联作品与资料</summary><div class="tag-related">${t.games.slice(0,8).map(g=>`<button data-action="detail" data-id="${g.id}">${esc(title(g))}</button>`).join('')}${t.games.length>8?`<span>共 ${t.games.length} 部，点击标签查看全部</span>`:''}${t.entity?`<button class="tag-wiki" data-action="tag-wiki" data-url="${esc(t.entity.url)}">Bangumi 会社资料 ↗</button>`:''}</div></details></article>`).join('')||'<p class="form-help">没有找到这个标签。换个别名搜索，或先匹配游戏资料。</p>';}
function updateTagCatalog(){const list=$('#tag-catalog');if(list)list.innerHTML=tagCatalog();const count=$('#sidebar-picked-count');if(count)count.textContent=sidebarSelectedCount();}

const visibleGames=()=>data.games.filter(g=>!g.hidden);
const gameById=id=>data.games.find(g=>g.id===id);
const active=id=>data.active.find(r=>r.gameId===id);
const title=g=>g.displayTitle||g.title;
const cover=g=>(g.customCover||g.metadata?.cover)?`app://shiori/cover/${g.id}?v=${encodeURIComponent(g.customCover||g.metadata?.fetchedAt||'local')}`:null;
const time=s=>{s=Math.max(0,Math.floor(s||0));if(s<60)return `${s} 秒`;if(s<3600)return `${Math.floor(s/60)} 分钟`;return `${Math.floor(s/3600)} 小时 ${Math.floor(s%3600/60)} 分钟`;};
const shortTime=s=>(s||0)>=3600?`${((s||0)/3600).toFixed(1)} h`:(s||0)>=60?`${Math.floor(s/60)} min`:(s||0)>0?`${Math.floor(s)} 秒`:'尚未游玩';
const date=s=>s?new Date(s).toLocaleDateString('zh-CN',{month:'2-digit',day:'2-digit'}):'—';
const fullDate=s=>s?new Date(s).toLocaleString('zh-CN',{hour12:false}):(s||0)>0?`${Math.floor(s)} 秒`:'尚未游玩';
const button=(action,label,ico,cls='',attrs='')=>`<button class="button ${cls}" data-action="${action}" ${attrs}>${ico?icon(ico):''}${label}</button>`;
function toast(message){const e=$('#toast');e.textContent=String(message).replace(/^Error invoking remote method '[^']+': Error: /,'');e.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>e.classList.remove('visible'),5500);}
async function run(fn,success){try{const result=await fn();if(success&&result!==false)toast(success);return result;}catch(e){toast(e.message);return undefined;}}
function counts(type){const map=new Map();for(const g of visibleGames())for(const t of new Set(g.tags[type]||[]))map.set(t,(map.get(t)||0)+1);return [...map.entries()].sort((a,b)=>b[1]-a[1]||a[0].localeCompare(b[0],'zh-CN'));}
function writerCounts(){return data.settings.showWriterFilters===false?[]:counts('writers').filter(([name])=>(data.settings.visibleWriters||[]).includes(name));}
function filterChip(type,value,count){const on=filters.some(f=>f.type===type&&f.value===value);return `<button class="chip ${on?'active':''}" data-action="filter" data-type="${type}" data-value="${esc(value)}">${esc(value)}${count?`<small>${count}</small>`:''}${on?icon('close'):''}</button>`;}
function category(type,value,count){const on=filters.some(f=>f.type===type&&f.value===value);return `<button class="category ${on?'active':''}" data-action="filter" data-type="${type}" data-value="${esc(value)}"><span class="tiny-dot ${type==='writers'?'dot-green':''}"></span><span>${esc(value)}</span><b>${count}</b></button>`;}
function sidebar(){const groups=tagKinds.map(([type,name,en])=>({type,name,en,items:counts(type).filter(([value])=>(data.settings.sidebarTags?.[type]||[]).includes(value))})).filter(g=>g.items.length&&(g.type!=='writers'||data.settings.showWriterFilters!==false));return `<aside class="sidebar"><div class="brand"><img src="icon.png" alt=""><div><strong>栞</strong><small>SHIORI</small></div></div><nav class="nav" aria-label="主导航">${[['library','grid','我的收藏'],['records','clock','游玩记录'],['tags','tag','标签一览']].map(([id,ico,label])=>`<button class="${view===id?'active':''}" data-action="navigate" data-view="${id}">${icon(ico)}${label}${id==='library'?`<span class="count">${visibleGames().length}</span>`:''}</button>`).join('')}</nav><div class="sidebar-scroll">${groups.map(group=>`<div class="category-title">${group.name} / ${group.en}</div>${group.items.slice(0,sidebarExpanded.has(group.type)?9999:8).map(x=>category(group.type,...x)).join('')}${group.items.length>8?`<button class="more" data-action="expand-sidebar" data-type="${group.type}">${sidebarExpanded.has(group.type)?'收起':'查看全部已固定 '+group.items.length+' 个标签'} ›</button>`:''}`).join('')}${!groups.length?'<p class="form-help sidebar-empty">还没有固定标签。<br>到标签一览勾选并保存，侧栏只展示你确认的分类。</p>':''}<button class="more" data-action="navigate" data-view="tags">管理侧栏标签 ›</button></div><div class="sidebar-bottom"><p><span class="live-dot"></span>${data.scanning?'正在扫描游戏目录':data.settings.roots.length?'游戏目录自动发现已开启':'选择目录后开启自动发现'}</p><button data-action="navigate" data-view="settings">${icon('settings')}偏好设置</button><div class="version-label">栞 SHIORI · 开源版 <span>v0.5.0</span></div></div></aside>`;}
function titlebar(){return `<header class="titlebar"><div class="breadcrumb">我的空间<span>/</span>${{library:'Galgame 收藏馆',records:'游玩记录',tags:'标签一览',settings:'偏好设置',setup:'首次设置'}[view]}</div><label class="search">${icon('search')}<input id="search" type="search" placeholder="搜索游戏、系列、会社、脚本家…" value="${esc(query)}" aria-label="搜索游戏"><kbd>Ctrl K</kbd></label><div class="window-controls"><button data-action="window" data-value="minimize" aria-label="最小化">${icon('minus')}</button><button data-action="window" data-value="maximize" aria-label="最大化">${icon('square')}</button><button data-action="window" data-value="close" aria-label="关闭窗口">${icon('close')}</button></div></header>`;}
function filtered(){let games=visibleGames();if(tab==='favorite')games=games.filter(g=>g.favorite);else if(tab==='review')games=games.filter(g=>g.confidence==='review'||g.metadataState!=='matched');else if(tab!=='all')games=games.filter(g=>g.status===tab);if(query.trim()){const compact=s=>String(s||'').normalize('NFKC').toLocaleLowerCase().replace(/\s/g,'');const q=compact(query);games=games.filter(g=>compact([g.title,g.displayTitle,g.relativePath,g.metadata?.originalTitle,...(g.metadata?.writers||[]),...(g.fanMetadata?.writers||[]),...Object.values(g.tags).flat(),...(data.companyEntities||[]).filter(e=>g.tags.companies.includes(e.name)).flatMap(e=>e.aliases)].join(' ')).includes(q));}if(filters.length)games=games.filter(g=>filterMode==='and'?filters.every(f=>(g.tags[f.type]||[]).includes(f.value)):filters.some(f=>(g.tags[f.type]||[]).includes(f.value)));
  return games.sort((a,b)=>sort==='title'?title(a).localeCompare(title(b),'zh-CN'):sort==='time'?(b.playSeconds||0)-(a.playSeconds||0):sort==='rating'?(b.metadata?.rating||0)-(a.metadata?.rating||0):sort==='recent'?(b.lastPlayed||'').localeCompare(a.lastPlayed||''):(b.addedAt||'').localeCompare(a.addedAt||'')||Number(!!cover(b))-Number(!!cover(a))||title(a).localeCompare(title(b),'zh-CN'));}
function coverHTML(g,cls=''){const c=cover(g);return c?`<img class="${cls}" src="${c}" alt="${esc(title(g))}" loading="lazy">`:`<div class="cover-fallback ${cls}" style="--hue:${(parseInt(g.id.slice(0,4),16)%100)+220}"><span class="fallback-mark">栞</span><strong>${esc(title(g))}</strong><small>YOUR NEXT STORY</small></div>`;}
function card(g){const r=active(g.id);return `<article class="game-card ${selectionMode?'selectable':''} ${selectedGames.has(g.id)?'selected':''}" data-action="detail" data-id="${g.id}" tabindex="0" role="button" aria-label="查看 ${esc(title(g))}"><div class="cover-wrap">${selectionMode?`<span class="select-box">${selectedGames.has(g.id)?icon('check'):''}</span>`:''}${coverHTML(g)}<div class="cover-gradient"></div>${r?`<span class="cover-badge running">${r.paused?'计时已暂停':r.phase==='running'?'● 正在游玩':r.phase==='no-window'?'未发现游戏窗口':'正在启动…'}</span>`:g.missing?'<span class="cover-badge">文件缺失</span>':g.kind==='rom'?'<span class="cover-badge">模拟器游戏</span>':''}<button class="cover-favorite ${g.favorite?'on':''}" data-action="favorite" data-id="${g.id}" aria-label="${g.favorite?'取消收藏':'收藏'}">${icon('heart')}</button>${g.metadata?.rating?`<span class="cover-rating" title="${esc(g.metadata.source||'Bangumi')} 评分">${icon('star')}${g.metadata.rating.toFixed(1)} <small style="font-size:8px;opacity:.8">${g.metadata.source==='VNDB'?'VNDB':'BGM'}</small></span>`:''}<button class="quick-play" data-action="launch" data-id="${g.id}" aria-label="启动 ${esc(title(g))}">${icon('play')}</button></div><h3 title="${esc(title(g))}">${esc(title(g))}</h3><div class="company">${esc(g.tags.companies.slice(0,2).join(' · ')||g.tags.writers[0]||'等待补全资料')}</div><div class="card-meta"><button class="status-toggle" data-action="complete" data-id="${g.id}" title="${g.status==='completed'?'取消通关标记':'标记为已通关'}"><i class="state-dot ${g.status}"></i>${statuses[g.status]}</button><span data-playtime="${g.id}">${icon('clock')}${shortTime(g.playSeconds)}</span></div></article>`;}
function heading(eyebrow,h1,p,actions=''){return `<div class="page-heading"><div><div class="eyebrow">${eyebrow}</div><h1>${h1}</h1><p>${p}</p></div><div class="heading-actions">${actions}</div></div>`;}
function libraryPage(){const games=visibleGames(),total=games.reduce((n,g)=>n+(g.playSeconds||0),0),recent=[...games].filter(g=>g.lastPlayed).sort((a,b)=>b.lastPlayed.localeCompare(a.lastPlayed))[0];const feature=recent||games.find(g=>/樱之诗|蒼|Aokana|白日梦|白昼夢/.test(g.title)&&cover(g))||games.find(g=>cover(g));const results=filtered();return `${heading('YOUR PERSONAL VISUAL NOVEL LIBRARY','我的收藏','让每个故事，都有栖身之处。',button('batch-mode',selectionMode?'取消选择':'批量标记通关','check')+button('scan',data.scanning?'扫描中…':'扫描目录','refresh','',data.scanning?'disabled':'')+button('import-executable','添加 EXE','folder')+button('add-root','添加游戏目录','plus','primary'))}<div class="hero-row"><section class="hero"><div class="hero-orbit"></div><div class="hero-copy"><div class="eyebrow">${recent?'CONTINUE YOUR STORY':'A LITTLE PLACE FOR ALL YOUR STORIES'}</div><h2>${heroGreeting(!!recent)}</h2><p>${feature?`${recent?'继续游玩':'今日书签'} · ${esc(title(feature))}`:'把喜欢的故事收藏起来，慢慢相遇。'}</p>${feature?button(recent?'launch':'detail',recent?'继续游玩':'翻开这个故事',recent?'play':'book','primary',`data-id="${feature.id}"`):button('scan','发现我的游戏','sparkles','primary')}</div>${feature?coverHTML(feature,'hero-cover'):'<div class="hero-no-cover">栞</div>'}<span class="hero-footer">STORIES, KEPT CLOSE. <button data-action="hero-next" class="hero-copy-next" aria-label="换一句欢迎语">换一句 ${icon('refresh')}</button></span></section><section class="collection-stats"><p>${icon('leaf')}收藏里的时光</p><div class="stat-row"><span>收藏游戏</span><strong>${games.length}<small>部</small></strong></div><div class="stat-row"><span>累计游玩</span><strong data-total-playtime>${(total/3600).toFixed(1)}<small>小时</small></strong></div><div class="stat-row"><span>已通关</span><strong>${games.filter(g=>g.status==='completed').length}<small>部</small></strong></div><div class="stat-note">每一段时光，都值得被记住。</div></section></div><div class="library-tools"><div class="tabs">${[['all','全部游戏'],['playing','游玩中'],['unplayed','未开始'],['completed','已通关'],['favorite','我的收藏']].map(([id,label])=>`<button class="tab ${tab===id?'active':''}" data-action="tab" data-value="${id}">${label}${id==='all'?`<small>${games.length}</small>`:''}</button>`).join('')}</div><div class="view-tools"><select id="sort" aria-label="游戏排序">${[['added','最近添加'],['recent','最近游玩'],['title','名称排序'],['time','游玩时长'],['rating','资料源评分']].map(([v,t])=>`<option value="${v}" ${sort===v?'selected':''}>${t}</option>`).join('')}</select><button class="icon-button ${!listMode?'active':''}" data-action="layout" data-value="grid" aria-label="封面视图">${icon('grid')}</button><button class="icon-button ${listMode?'active':''}" data-action="layout" data-value="list" aria-label="列表视图">${icon('list')}</button></div></div><div class="filter-row"><span class="filter-caption">${icon('filter')}${filters.length?'筛选标签':'快捷标签'}</span>${filters.length?filters.map(f=>filterChip(f.type,f.value)).join(''):(counts('series').length?counts('series').slice(0,6).map(([name,n])=>filterChip('series',name,n)):counts('folders').filter(([name])=>!counts('companies').some(([c])=>c===name)).slice(0,6).map(([name])=>filterChip('folders',name))).join('')}${filters.length?`<button class="clear-filters" data-action="clear-filters">清除筛选</button>`:''}<span class="result-count">${results.length} 个故事</span></div>${selectionMode?batchPanel():''}<div class="games-grid ${listMode?'list-mode':''}">${results.length?results.map(card).join(''):`<div class="empty" style="grid-column:1/-1">${icon('search')}<h3>${games.length?'还没有找到这个故事':'这里，等着你的第一个故事'}</h3><p>${games.length?'试着换个关键词，或减少筛选标签。':'将游戏解压到游戏目录，栞会自动发现。'}</p>${button('clear-filters','清除筛选','refresh')}</div>`}</div>${footer()}`;}
function footer(){return `<footer class="library-footer"><span class="live-dot"></span>${data.metadataProgress?`正在补全资料 ${data.metadataProgress.done}/${data.metadataProgress.total} · ${esc(data.metadataProgress.title)}`:`${data.lastScan?`上次扫描 ${new Date(data.lastScan.at).toLocaleTimeString('zh-CN',{hour12:false})} · 自动监测目录变化`:'正在准备游戏库'}`}<span>所有游玩记录 · 保存在本机</span></footer>`;}
function recordsPage(){const games=visibleGames(),sessions=data.sessions.filter(s=>s.seconds>0),total=games.reduce((n,g)=>n+(g.playSeconds||0),0),days={};for(const s of sessions)for(const [d,t] of Object.entries(s.days||{}))days[d]=(days[d]||0)+t;const today=new Date();const keys=Array.from({length:14},(_,i)=>{const d=new Date(today);d.setDate(d.getDate()-13+i);return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;});const max=Math.max(...keys.map(k=>days[k]||0),60);const rows=[...sessions].reverse();return `${heading('YOUR TIME, YOUR STORIES','游玩记录','那些与你一起度过的时间。',button('export','导出记录','download'))}<div class="stats-overview">${[['累计游玩',(total/3600).toFixed(1),'小时'],['游玩次数',sessions.length,'次'],['今日游玩',((days[keys.at(-1)]||0)/3600).toFixed(1),'小时'],['活跃天数',Object.keys(days).length,'天']].map(([l,n,u])=>`<div class="metric"><label>${l}</label><strong>${n}<small>${u}</small></strong></div>`).join('')}</div><div class="chart-panel"><h3>最近两周 · 游玩时光</h3><div class="bar-chart">${keys.map(k=>`<div class="bar-column" title="${k} · ${time(days[k]||0)}"><span>${days[k]?`${(days[k]/3600).toFixed(1)}h`:''}</span><div class="bar" style="height:${Math.max(3,(days[k]||0)/max*115)}px"></div><small>${k.slice(5).replace('-','/')}</small></div>`).join('')}</div></div><div class="chart-panel"><h3>最近的故事</h3>${rows.length?rows.slice(0,80).map(s=>{const g=gameById(s.gameId);return `<div class="record-row"><div>${g?`<button data-action="detail" data-id="${g.id}"><strong>${esc(title(g))}</strong></button>`:'已移除的游戏'}<p>${fullDate(s.startedAt)} ${s.endedAt?'— '+new Date(s.endedAt).toLocaleTimeString('zh-CN',{hour12:false}):'· 正在记录'}${s.interrupted?' · 上次异常中断':''}</p></div><span>${time(s.seconds)}</span></div>`;}).join(''):`<div class="empty">${icon('clock')}<h3>时光，从第一次启动开始</h3><p>从栞启动游戏后，游玩记录会自动出现在这里。<br>关闭窗口后，运行中的游戏会继续在托盘计时。</p></div>`}</div>`;}
function tagsPage(){ensureSidebarDraft();return `${heading('FIND STORIES YOUR WAY','标签一览','核对来源、别名和关联作品，勾选并保存后才会显示到侧栏。',button('refresh-companies',data.companyRefreshing?'会社核对中…':'按 Bangumi 核对会社','refresh','',data.companyRefreshing?'disabled':''))}<div class="tag-manager"><div class="tag-manager-toolbar"><label class="tag-search-label">${icon('search')}<input id="tag-query" type="search" value="${esc(tagQuery)}" placeholder="搜索标签或别名" aria-label="搜索标签或别名"></label><span>已勾选 <b id="sidebar-picked-count">${sidebarSelectedCount()}</b> 个</span>${button('save-sidebar-tags','保存侧栏标签','check','primary')}${button('reset-sidebar-tags','撤销未保存修改',null,'small')}</div><div class="tag-kind-tabs">${tagKinds.map(([type,name])=>`<button data-action="tag-type" data-type="${type}" class="${type===tagType?'active':''}">${name}<small>${counts(type).length}</small></button>`).join('')}</div><div class="tag-manager-note"><span>${tagType==='companies'?'以 Bangumi 游戏条目和会社身份为主，发行商单独记录；目录推测和其他来源会明确标注。':tagType==='genres'?'保留作品知识库中的题材与玩法等标签，不将它们混入会社或脚本家。':'这里展示完整标签，不受侧栏固定名单限制。点击名称筛选作品，勾选只修改待保存的侧栏名单。'}</span><button data-action="pin-visible-tags">勾选当前结果</button><button data-action="unpin-visible-tags">取消当前结果</button></div><div id="tag-catalog" class="tag-catalog">${tagCatalog()}</div></div>`;}
function rootList(){return data.settings.roots.length?data.settings.roots.map(root=>`<div class="root-path managed-root">${icon('folder')}<span>${esc(root)}</span><button class="button small" data-action="remove-root" data-root="${esc(root)}" aria-label="停止扫描 ${esc(root)}">停止扫描</button></div>`).join(''):'<p class="form-help">还没有选择目录。可以添加多个磁盘上的文件夹，保留原来的分类结构。</p>';}
function onboardingPage(){return `${heading('A NEW PLACE FOR YOUR STORIES','给故事找个位置','从你自己的游戏目录开始，原来的文件不需要搬动。')}<div class="setup-grid"><section class="setting-panel setup-directory"><span class="setup-step">01 / 游戏目录</span><h2>把你的收藏带进来</h2><p>选择一个或多个文件夹，自动查找各级目录中的游戏启动程序；会社、脚本家、系列和原目录分别整理。扫描只收录文件，点击「开始游玩」才会运行游戏。</p>${rootList()}<div class="setup-actions">${button('add-root','选择游戏目录','folder','primary')}${button('import-executable','直接添加 EXE','plus')}</div><p class="form-help">解压新游戏后自动发现。多个启动文件难以判断时，会请你确认。</p></section><section class="setting-panel setup-account"><span class="setup-step">02 / 在线资料（可选）</span>${tokenPanel()}</section></div><div class="setup-finish"><p>可以先导入游戏，之后再连接 Bangumi。</p>${button('finish-setup',data.settings.roots.length||data.games.length?'进入我的收藏':'稍后设置，先看看','chevron','primary')}</div>`;}
function settingsPage(){return `${heading('MAKE YOURSELF AT HOME','偏好设置','给你的故事，安排一个舒适的位置。')}<div class="setting-panel"><h3>游戏所在的目录</h3><p>选择多个目录，自动保留原来的分类；目录变化稳定约 7 秒后扫描，每 60 秒复查。停止扫描只移除监听，已收录的游戏、标签和游玩记录继续保留。</p>${rootList()}<div class="setup-actions">${button('add-root','添加游戏目录','plus')}${button('scan','立即扫描','refresh')}${button('import-executable','直接添加 EXE','folder')}</div>${data.lastScan?.warnings?.length?`<p>扫描提示：${data.lastScan.warnings.map(w=>esc(w.path)+' · '+esc(w.message)).join('<br>')}</p>`:''}</div>${tokenPanel()}<div class="setting-panel"><h3>自动补全与社区</h3><div class="setting-line"><div><strong>从 Bangumi / VNDB 匹配资料</strong><small>补充封面、介绍、会社、脚本家与资料源评分。只接受游戏条目；同名或版本不确定时由你确认。<br>2DFan 补充公开资料与作品入口，网络不可用时仍能启动和计时。</small></div><button class="toggle ${data.settings.autoMetadata?'on':''}" data-action="toggle-metadata" role="switch" aria-checked="${data.settings.autoMetadata}" aria-label="自动补全资料"></button></div>${button('retry-metadata','重试未匹配的资料','refresh','small')}<p>已匹配 ${visibleGames().filter(g=>g.metadataState==='matched').length} · 待确认 ${visibleGames().filter(g=>g.metadataState==='review').length} · 未找到 ${visibleGames().filter(g=>g.metadataState==='not-found').length} · 网络失败 ${visibleGames().filter(g=>g.metadataState==='error').length}</p><p>详情页可打开 Bangumi、VNDB、2DFan 的作品页，在平台网站登录后参与评分、阅读讨论和攻略。VNDB 公共游戏资料不需要 Token，2DFan 暂不提供账号连接。</p></div>${localePanel()}${writerPanel()}<div class="setting-panel"><h3>本地数据与计时</h3><p>根据实际游戏进程记录时长，可暂停或结束计时；电脑休眠期间不计时。关闭窗口时，如果游戏仍在运行，栞会留在托盘继续记录。每 10 秒保存进度，并保留最近 14 天的每日快照。</p><div class="setting-line"><strong>${data.monitor==='ok'?'进程监控已连接':data.monitor==='starting'?'进程监控连接中':'进程监控暂不可用'}</strong></div><div class="setup-actions">${button('export','导出资料与游玩记录','download')}${button('data-folder','打开数据目录','folder')}</div></div>${hiddenPanel()}<div class="setting-panel"><h3>关于栞 Shiori · 开源版</h3><p>Windows 本地视觉小说收藏馆 · v0.5.0<br>程序代码采用 MIT 许可；封面和数据库资料的权利归原平台及作者。${button('open-setup','重新打开设置向导',null,'small')}</p></div>`;}
function render(){const focused=document.activeElement?.id,selection=focused==='search'?$('#search').selectionStart:null;$('#app').innerHTML=`<div class="shell">${sidebar()}<div class="main">${titlebar()}<main class="content">${page()}</main></div></div>`;if(focused==='search'){const s=$('#search');s.focus();try{s.setSelectionRange(selection,selection);}catch{}}}
function batchPanel(){return `<div class="batch-panel"><span>已选择 <strong>${selectedGames.size}</strong> 部游戏</span><button data-action="batch-select-all">选择当前结果</button><button data-action="batch-clear">清空选择</button><select id="batch-status" aria-label="批量标记状态">${Object.entries(statuses).map(([v,t])=>`<option value="${v}" ${v==='completed'?'selected':''}>${t}</option>`).join('')}</select>${button('batch-apply','应用标记','check','primary small')}</div>`;}
function tokenPanel(){return `<div class="setting-panel"><h3>连接你自己的 Bangumi</h3><p>打开官方页面注册或登录账号，创建个人访问令牌，再粘贴到这里。部分游戏条目需要登录权限；也可以稍后连接。</p><div class="setting-line"><div><strong>${data.settings.hasBangumiToken?'已连接：'+esc(data.settings.bangumiUser||'Bangumi'):'尚未连接 Bangumi'}</strong><small>Token 使用 Windows 加密保存在本机，只发送给 Bangumi；不包含在游戏库导出中。</small></div>${button('bangumi-login','登录 / 创建 Token','external','small')}</div><form id="bangumi-token-form" class="token-form"><input name="token" type="password" autocomplete="off" placeholder="粘贴 Bangumi 个人访问令牌" class="match-input" aria-label="Bangumi 访问令牌" required><button type="submit" class="button primary">连接并补全</button></form><p class="form-help">栞读取游戏资料，不会自动发布评分、评论或修改平台收藏。社区操作在对应网站中由你完成。</p>${data.settings.hasBangumiToken?button('disconnect-bangumi','断开连接',null,'small'):''}</div>`;}
function hiddenPanel(){const hidden=data.games.filter(g=>g.hidden);return hidden.length?`<div class="setting-panel"><h3>隐藏的条目</h3>${hidden.map(g=>`<div class="setting-line"><strong>${esc(title(g))}</strong>${button('restore-game','恢复显示',null,'small',`data-id="${g.id}"`)}</div>`).join('')}</div>`:'';}
function localePanel(){return `<div class="setting-panel"><h3>LE 转区启动</h3><p>可选择你已经安装的 Locale Emulator，普通游戏无需启用。在游戏详情中勾选「LE 转区启动」后，每次启动都会使用该游戏已有的 LE 配置；没有独立配置时使用默认日语环境。</p><div class="root-path">${esc(data.settings.localeEmulatorPath||'尚未找到 LEProc.exe')}</div>${button('choose-locale','选择 LEProc.exe','folder','small')}</div>`;}
function writerPanel(){return `<div class="setting-panel"><h3>侧栏标签与脚本家</h3><p>会社、系列、脚本家、作品标签等统一在「标签一览」勾选保存。侧栏只展示你确认的标签，完整资料和搜索仍然保留。</p>${button('navigate','管理侧栏标签','tag','small','data-view="tags"')}<div class="setting-line"><span>在侧栏显示已固定的脚本家</span><button class="toggle ${data.settings.showWriterFilters!==false?'on':''}" data-action="toggle-writers" role="switch" aria-checked="${data.settings.showWriterFilters!==false}"></button></div></div>`;}
function writerOptionsHTML(){const compact=value=>String(value||'').normalize('NFKC').toLowerCase().replace(/\s/g,'');const q=compact(writerSearch);const all=counts('writers').filter(([name])=>[name,...(data.authors?.find(a=>a.name===name)?.aliases||[])].some(alias=>compact(alias).includes(q))).sort((a,b)=>Number(writerSelection.has(b[0]))-Number(writerSelection.has(a[0])));return all.map(([name,n])=>`<label title="${esc((data.authors?.find(a=>a.name===name)?.aliases||[name]).join(' / '))}"><input type="checkbox" data-writer="${esc(name)}" ${writerSelection.has(name)?'checked':''}><span>${esc(name)}</span><small>${n} 部</small></label>`).join('')||'<p class="form-help">没有找到，试试原名或别名。</p>';}
function updateWriterOptions(){const list=$('.writer-options');if(list){list.innerHTML=writerOptionsHTML();list.scrollTop=0;}const count=$('#writer-selected-count');if(count)count.textContent=writerSelection.size;}
function renderWriterManager(){$('#overlay').innerHTML=`<div class="scrim modal-scrim" data-dismiss="true"><section class="modal" role="dialog" aria-modal="true" aria-label="选择关注的脚本家"><button class="drawer-close" data-action="close-overlay" aria-label="关闭">${icon('close')}</button><h2>只看你想关注的脚本家</h2><p>支持中文、日文、英文和作者别名，例如「濑户口」「瀬戸口」。已关注的作者优先显示，同一作者的不同署名会合并。</p><input id="writer-search" class="match-input" value="${esc(writerSearch)}" placeholder="搜索姓名或别名（中文 / 日文 / 英文）" aria-label="搜索脚本家"><div class="writer-options">${writerOptionsHTML()}</div><div class="form-actions"><span style="margin-right:auto;color:#ad9cbb;font-size:11px">已选择 <b id="writer-selected-count">${writerSelection.size}</b> 位</span>${button('save-writers','保存名单','check','primary')}</div></section></div>`;}

function fontCredit(){return '<p class="font-credit">标题字体：得意黑 · atelierAnchor；正文字体：MiSans · Xiaomi Inc.</p>';}
function page(){return view==='setup'?onboardingPage():view==='records'?recordsPage():view==='tags'?tagsPage():view==='settings'?settingsPage()+fontCredit():libraryPage();}
function renderContent(){const el=$('.content'),top=el.scrollTop;el.innerHTML=page();el.scrollTop=top;}
function updateSidebar(){const side=$('.sidebar');side.outerHTML=sidebar();}
function tagLines(g){return [['companies','会社'],['series','系列'],['writers','脚本家'],['genres','作品标签'],['folders','目录'],['custom','标签']].filter(([t])=>g.tags[t]?.length&&(t!=='writers'||g.showWriterTags!==false)).map(([t,l])=>`<div class="tag-line"><label>${l}</label><div class="tag-list">${g.tags[t].map(v=>filterChip(t,v)).join('')}</div></div>`).join('')+(g.companySource?`<p class="form-help">会社来源：${esc(g.companySource.source)}${g.companySource.url?` <button data-action="tag-wiki" data-url="${esc(g.companySource.url)}">查看资料 ↗</button>`:''}${g.companySource.publishers.length?`<br>发行：${g.companySource.publishers.map(esc).join('、')}（不作为开发会社标签）`:''}</p>`:'');}
function detail(id){selectedId=id;editing=false;matchingId=null;renderDrawer();}
function renderDrawer(){const g=gameById(selectedId);if(!g)return;const r=active(g.id),sessions=data.sessions.filter(s=>s.gameId===g.id).slice(-5).reverse(),bgm=g.bangumiUrl||(g.metadata?.source!=='VNDB'?g.metadata?.url:null);
  $('#overlay').innerHTML=`<div class="scrim" data-dismiss="true"><section class="drawer" role="dialog" aria-modal="true" aria-label="${esc(title(g))}"><div class="drawer-hero">${coverHTML(g,'drawer-cover')}<div class="drawer-hero-copy"><div class="eyebrow">${g.kind==='rom'?'EMULATED VISUAL NOVEL':'A STORY IN YOUR COLLECTION'}</div><h2>${esc(title(g))}</h2><p>${esc(g.metadata?.originalTitle||g.title)}</p>${g.metadata?.rating?`<p style="margin-top:9px;color:#b18e63">${icon('star')} ${g.metadata.rating.toFixed(1)} <span style="color:#b0a4bd;font-size:9px">${esc(g.metadata.source||'Bangumi')} · ${g.metadata.votes} 人评价</span></p>`:''}</div><button class="drawer-close" data-action="close-overlay" aria-label="关闭详情">${icon('close')}</button></div><div class="drawer-body">${editing?editForm(g):`<div class="detail-actions">${r?button('pause',r.paused?'继续计时':'暂停计时',r.paused?'play':'pause','primary',`data-id="${g.id}"`):button('launch',g.kind==='rom'?'用模拟器启动':'开始游玩','play','primary',`data-id="${g.id}"`)}${r?button('finish','结束计时','stop','',`data-id="${g.id}"`):''}<button class="button ${g.favorite?'soft':''}" data-action="favorite" data-id="${g.id}" aria-label="收藏">${icon('heart')}</button>${button('edit','编辑资料','edit','',`data-id="${g.id}"`)}<select id="detail-status" data-id="${g.id}" aria-label="游玩状态">${Object.entries(statuses).map(([v,t])=>`<option value="${v}" ${g.status===v?'selected':''}>${t}</option>`).join('')}</select></div><label class="launch-option"><input id="detail-locale" type="checkbox" data-id="${g.id}" ${g.useLocaleEmulator?'checked':''}> LE 转区启动（日语 / 已有配置）</label>${g.lastLaunchIssue?`<div class="info-notice" role="alert">${esc(g.lastLaunchIssue.message)}</div>`:''}<div class="detail-stats"><div><label>累计游玩</label><strong data-playtime="${g.id}">${shortTime(g.playSeconds)==='尚未游玩'?'0 分钟':shortTime(g.playSeconds)}</strong></div><div><label>游玩次数</label><strong>${data.sessions.filter(s=>s.gameId===g.id).length} <small style="font-size:10px">次</small></strong></div><div><label>上次游玩</label><strong class="small-text">${g.lastPlayed?date(g.lastPlayed):'等待相遇'}</strong></div></div>${r?`<div class="info-notice">${r.paused?'计时已暂停':r.phase==='running'?'正在记录本次游玩':r.phase==='no-window'?'游戏进程在后台，未发现窗口':'正在启动，等待游戏窗口'} · <span data-sessiontime="${g.id}">${time(r.seconds)}</span>${data.monitor!=='ok'?' · 进程监控连接中':''}<br>「结束计时」只保存记录，游戏会继续运行。</div>`:''}${g.missing?'<div class="info-notice">游戏文件当前不在原位置。接回磁盘或恢复目录后重新扫描，已有记录会保留。</div>':''}${g.confidence==='review'&&!g.manualLaunch?`<div class="info-notice">发现多个可能的启动程序，建议先在编辑资料中确认。<br>当前选择：${esc(g.launchPath.split(/[\\/]/).pop())}</div>`:''}${g.kind==='rom'&&!g.emulatorPath?'<div class="info-notice">这是主机游戏镜像，请在编辑资料中选择模拟器并填写所需参数。</div>':''}<section class="detail-section"><h3>${icon('external')}社区与资料</h3><div class="external-cards">${[['bangumi','B','Bangumi','作品 · 评分 · 讨论','bangumi'],['vndb','VN','VNDB','作品 · 评分 · 讨论','vndb'],['2dfan','2DF','2DFan','资料 · 评价 · 攻略','fan']].map(([action,logo,name,description,key])=>`<button class="external-card" data-action="${action}" data-id="${g.id}"><span class="site-logo ${key!=='bangumi'?'fan':''}">${logo}</span><span><strong>${name}</strong><small>${g.community[key].matched?description:'搜索作品，确认后保存链接'}</small></span>${icon('external')}</button>`).join('')}</div><p class="form-help">将在浏览器打开对应平台。尚未关联的入口会搜索游戏名，不会冒用其他作品的评分。</p></section><section class="detail-section"><h3>${icon('tag')}故事的索引</h3>${tagLines(g)||'<p class="form-help">匹配资料，或手动添加你的标签。</p>'}</section><section class="detail-section"><h3>${icon('book')}关于这个故事 <button class="section-action" data-action="match" data-id="${g.id}">${g.metadata?'重新匹配资料':'匹配游戏资料'} ›</button></h3><div class="summary">${esc(g.metadata?.summary||'还没有这个故事的介绍。匹配 Bangumi 资料后，封面、评分、会社和脚本家会一起补充到这里。')}</div>${g.metadataState==='error'?'<p class="form-help">上次联网查询未成功，可以手动重试。</p>':''}${g.metadataState==='review'?'<p class="form-help">找到相近的作品，等待你确认正确条目。</p>':''}</section><section class="detail-section"><h3>${icon('edit')}我的手记 <button class="section-action" data-action="edit" data-id="${g.id}">写下几句 ›</button></h3><div class="note-box">${esc(g.notes||'喜欢的台词、下一条想走的路线、关于它的一点心情…')}</div></section>${sessions.length?`<section class="detail-section"><h3>${icon('clock')}最近游玩</h3>${sessions.map(s=>`<div class="session-row"><span>${fullDate(s.startedAt)}</span><strong>${time(s.seconds)}</strong></div>`).join('')}</section>`:''}<section class="detail-section"><h3>${icon('folder')}所在目录 <button class="section-action" data-action="open-folder" data-id="${g.id}">打开文件夹 ›</button></h3><div class="path-label">${esc(g.folder)}</div></section>`}</div></section></div>`;}
function editForm(g){return `<form class="edit-form" id="edit-form" data-id="${g.id}"><h3 style="font-size:15px;font-weight:500;margin:0 0 15px">编辑这个故事</h3><label for="f-title">显示名称</label><input id="f-title" name="customTitle" value="${esc(g.customTitle||title(g))}"><div class="two-cols"><div><label for="f-company">补充会社</label><input id="f-company" name="userCompanies" value="${esc((g.userCompanies||[]).join('，'))}" placeholder="例如：Key"></div><div><label for="f-writer">补充脚本家</label><input id="f-writer" name="userWriters" value="${esc((g.userWriters||[]).join('，'))}" placeholder="例如：田中罗密欧"></div></div><p class="form-help">多个值以逗号分隔；目录标签与匹配资料会自动保留。</p><label for="f-series">系列标签</label><input id="f-series" name="userSeries" list="series-options" value="${esc((g.userSeries||[]).join('，'))}" placeholder="例如：废村少女，9-nine-"><datalist id="series-options">${counts('series').map(([name])=>`<option value="${esc(name)}">`).join('')}</datalist><label class="series-auto"><input name="autoSeries" type="checkbox" ${g.autoSeries!==false?'checked':''}>同时使用自动识别的系列</label><p class="form-help">当前系列：${esc(g.tags.series.join('、')||'尚未识别')}。可补充多个系列；取消自动识别后，只使用你填写的系列。</p><label for="f-tags">自定义标签</label><input id="f-tags" name="userTags" value="${esc((g.userTags||[]).join('，'))}" placeholder="例如：纯爱，想重温，周末计划"><label>补录以前的游玩时长</label><div class="two-cols"><div><input id="f-history-hours" name="historyHours" type="number" min="0" max="200000" step="1" value="${Math.floor((g.historicalSeconds||0)/3600)}" aria-label="历史游玩小时数"><p class="form-help">小时</p></div><div><input id="f-history-minutes" name="historyMinutes" type="number" min="0" max="59" step="1" value="${Math.floor((g.historicalSeconds||0)%3600/60)}" aria-label="历史游玩分钟数"><p class="form-help">分钟</p></div></div><p class="form-help">补录部分会加入累计时长，并与自动计时分开保存，不会虚构过去的每日记录。</p><label for="f-notes">我的手记</label><textarea id="f-notes" name="notes" rows="4">${esc(g.notes||'')}</textarea><label for="f-bangumi">Bangumi 信息页（可留空使用自动匹配）</label><input id="f-bangumi" type="url" name="bangumiUrl" value="${esc(g.bangumiUrl||'')}" placeholder="https://bgm.tv/subject/…"><label for="f-vndb">VNDB 信息页（可留空使用自动匹配）</label><input id="f-vndb" type="url" name="vndbUrl" value="${esc(g.vndbUrl||'')}" placeholder="https://vndb.org/v…"><label for="f-fan">2DFan 信息页（可留空使用搜索）</label><input id="f-fan" type="url" name="fanUrl" value="${esc(g.fanUrl||'')}" placeholder="https://2dfan.com/subjects/…"><label>游戏封面</label>${button('choose-cover','从本地选择封面','book','small',`type="button" data-id="${g.id}"`)}<label style="display:flex;align-items:center;gap:9px"><input type="checkbox" name="showWriterTags" style="width:auto" ${g.showWriterTags!==false?'checked':''}>在这个游戏的详情中显示脚本家标签</label><label style="display:flex;align-items:center;gap:9px"><input type="checkbox" name="useLocaleEmulator" style="width:auto" ${g.useLocaleEmulator?'checked':''}>使用 LE 转区启动（日语 / 已有配置）</label><label>启动设置 · ${g.kind==='rom'?'游戏镜像':'可执行文件'}</label>${g.kind==='windows'?`<select id="candidate" data-id="${g.id}" aria-label="选择游戏启动程序">${g.candidates.map(c=>`<option value="${esc(c.path)}" ${g.launchPath===c.path?'selected':''}>${esc(c.name)}${g.candidates[0].path===c.path?' · 推荐':''}</option>`).join('')}${!g.candidates.some(c=>c.path===g.launchPath)?`<option selected value="${esc(g.launchPath)}">${esc(g.launchPath)}</option>`:''}</select>`:''}<div class="exe-field" style="margin-top:8px"><input readonly value="${esc(g.kind==='rom'?g.emulatorPath||'尚未选择模拟器':g.launchPath)}" aria-label="启动路径">${button('choose-exe',g.kind==='rom'?'选择模拟器':'浏览…','folder','small',`type="button" data-id="${g.id}" data-emulator="${g.kind==='rom'}"`)}</div><label for="f-args">启动参数（每行一个）</label><textarea id="f-args" name="launchArgs" rows="2" placeholder="可留空">${esc((g.launchArgs||[]).join('\n'))}</textarea><p class="form-help">每行作为一个完整参数，含空格的路径无需额外引号。{game} 会替换为游戏路径。<br>${g.kind==='rom'?'模拟器参数未包含 {game} 时，会自动把镜像路径追加到最后。':'也可以选择转区工具作为启动程序，再将游戏 EXE 的完整路径写为参数。'}</p><div class="form-actions">${button('hide-game','隐藏此条目',null,'danger small',`type="button" data-id="${g.id}"`)}${button('cancel-edit','返回',null,'',`type="button"`)}<button class="button primary" type="submit">${icon('check')}保存资料</button></div></form>`;}
function renderMatch(){const g=gameById(matchingId);if(!g)return;$('#overlay').innerHTML=`<div class="scrim modal-scrim" data-dismiss="true"><section class="modal" role="dialog" aria-modal="true" aria-label="匹配游戏资料"><button class="drawer-close" data-action="close-match" aria-label="关闭">${icon('close')}</button><div class="eyebrow" style="margin-bottom:12px">FIND THE RIGHT STORY</div><h2>匹配游戏资料</h2><p>为「${esc(title(g))}」搜索 Bangumi / VNDB，只展示游戏。也可粘贴作品链接，核对原名、发行日期和资料源后再关联。</p><form class="match-bar" id="match-form"><select id="match-provider" aria-label="资料源">${['all','Bangumi','VNDB'].map(value=>`<option value="${value}" ${value===matchProvider?'selected':''}>${value==='all'?'全部资料源':value}</option>`).join('')}</select><input class="match-input" id="match-query" name="query" value="${esc(matchQuery)}" placeholder="游戏名 / 作品链接 / bgm:123 / v123" aria-label="搜索游戏名"><button class="button primary" type="submit" ${matchResults==='loading'?'disabled':''}>${icon('search')}搜索</button></form>${matchWarnings.length?`<p class="info-notice" role="status">${matchWarnings.map(esc).join('<br>')}</p>`:''}<div id="match-results">${matchResults===null?'<div class="empty" style="padding:30px">换一个标题或粘贴条目链接，找到对应的故事。</div>':matchResults==='loading'?'<div class="empty" style="padding:35px">正在查询游戏数据库…</div>':matchResults.length?matchResults.map(x=>`<div class="match-result">${x.images?.small?`<img src="${esc(x.images.small)}" alt="">`:''}<div><strong>${esc(x.name_cn||x.name)}</strong><p>${esc(x.name)}<br>${esc(x.date||'日期未知')} · ${esc(x.provider||'Bangumi')} · 条目 ${esc(x.id)}${x.rating?.score?` · 评分 ${Number(x.rating.score).toFixed(1)}（${x.rating.total||0} 人）`:''}<br>名称匹配参考 ${Math.round(Math.max(0,Math.min(1,x.match))*100)}%，请核对版本。</p></div>${button('apply-match','关联这个作品','check','small',`data-id="${g.id}" data-subject="${x.id}"`)}</div>`).join(''):'<div class="empty" style="padding:30px">暂未找到。试试原文标题，或从作品页面复制链接。</div>'}</div></section></div>`;}
function closeOverlay(){selectedId=null;matchingId=null;editing=false;managingWriters=false;$('#overlay').innerHTML='';}
function stableSnapshot(x){return JSON.stringify({...x,games:x.games.map(({playSeconds,...g})=>g),sessions:x.sessions.map(({seconds,days,checkpoint,...s})=>s),active:x.active.map(({seconds,...r})=>r)});}
function updateClocks(){for(const el of document.querySelectorAll('[data-playtime]')){const g=gameById(el.dataset.playtime);if(g)el.innerHTML=el.tagName==='SPAN'?icon('clock')+shortTime(g.playSeconds):shortTime(g.playSeconds);}for(const el of document.querySelectorAll('[data-sessiontime]')){const r=active(el.dataset.sessiontime);if(r)el.textContent=time(r.seconds);}for(const el of document.querySelectorAll('[data-total-playtime]'))el.innerHTML=(visibleGames().reduce((n,g)=>n+(g.playSeconds||0),0)/3600).toFixed(1)+'<small>小时</small>';if(view==='records')renderContent();}
async function refresh(){if(refreshing)return;refreshing=true;try{const next=await api.getLibrary();const onlyTime=data&&stableSnapshot(data)===stableSnapshot(next);data=next;filters=filters.map(f=>f.type==='companies'?{...f,value:companyLabel(f.value)}:f);if(onlyTime){updateClocks();return;}if(document.activeElement?.closest('#bangumi-token-form')?.elements?.token?.value)return;const top=$('.content')?.scrollTop||0;if(document.activeElement?.id==='tag-query'){updateSidebar();updateTagCatalog();return;}if(document.activeElement?.id==='search'){updateSidebar();renderContent();}else{render();$('.content').scrollTop=top;}if(selectedId&&!editing&&!matchingId){const top=$('.drawer')?.scrollTop||0;renderDrawer();$('.scrim')?.classList.add('no-motion');if($('.drawer'))$('.drawer').scrollTop=top;}}finally{refreshing=false;}}
function toggleFilter(type,value){const same=filters.length===1&&filters[0].type===type&&filters[0].value===value;filters=same?[]:[{type,value}];filterMode='and';view='library';closeOverlay();render();}
document.addEventListener('click',async event=>{
  if(event.target.dataset.dismiss){closeOverlay();return;}
  const b=event.target.closest('[data-action]');if(!b)return;const action=b.dataset.action,id=b.dataset.id,g=id?gameById(id):null;
  if(b.disabled)return;
  if(action==='tag-type'){tagType=b.dataset.type;renderContent();}
  else if(action==='expand-sidebar'){if(sidebarExpanded.has(b.dataset.type))sidebarExpanded.delete(b.dataset.type);else sidebarExpanded.add(b.dataset.type);updateSidebar();}
  else if(action==='save-sidebar-tags'){ensureSidebarDraft();b.disabled=true;const ok=await run(()=>api.setSidebarTags(Object.fromEntries(Object.entries(sidebarDraft).map(([type,values])=>[type,[...values]]))),'侧栏标签已保存');if(ok){sidebarDraft=null;await refresh();if(view==='tags')renderContent();}}
  else if(action==='reset-sidebar-tags'){sidebarDraft=null;renderContent();}
  else if(action==='pin-visible-tags'||action==='unpin-visible-tags'){ensureSidebarDraft();for(const t of matchedTags()){if(action==='pin-visible-tags')sidebarDraft[tagType].add(t.name);else sidebarDraft[tagType].delete(t.name);}updateTagCatalog();}
  else if(action==='refresh-companies'){b.disabled=true;await run(()=>api.refreshCompanies(),'已开始按 Bangumi 核对会社，资料将在后台更新');await refresh();if(b.isConnected)b.disabled=!!data.companyRefreshing;}
  else if(action==='tag-wiki')await run(()=>api.openExternal(b.dataset.url));
  else if(action==='navigate'){view=b.dataset.view;closeOverlay();render();}
  else if(action==='hero-next'){const kind=visibleGames().some(g=>g.lastPlayed)?'continue':'discover';heroGreetingChoice[kind]=nextHeroGreeting(kind,heroGreetingChoice[kind]);renderContent();}
  else if(action==='window')api.windowAction(b.dataset.value);
  else if(action==='scan'){b.disabled=true;await run(()=>api.scan(),'游戏库已更新');await refresh();}
  else if(action==='add-root'){b.disabled=true;await run(()=>api.addRoot());await refresh();}
  else if(action==='remove-root'){await run(()=>api.removeRoot(b.dataset.root),'已停止扫描，游戏和记录已保留');await refresh();}
  else if(action==='import-executable'){const added=await run(()=>api.importExecutable());await refresh();if(added){view='library';render();detail(added);}}
  else if(action==='finish-setup'){await run(()=>api.updateSettings({onboardingCompleted:true}));view='library';await refresh();render();}
  else if(action==='open-setup'){view='setup';render();}
  else if(action==='expand-companies'){showAllCompanies=!showAllCompanies;updateSidebar();}
  else if(action==='expand-series'){showAllSeries=!showAllSeries;updateSidebar();}
  else if(action==='expand-writers'){showAllWriters=!showAllWriters;updateSidebar();}
  else if(action==='filter')toggleFilter(b.dataset.type,b.dataset.value);
  else if(action==='clear-filters'){filters=[];query='';tab='all';render();}
  else if(action==='tab'){tab=b.dataset.value;renderContent();}
  else if(action==='layout'){listMode=b.dataset.value==='list';renderContent();}
  else if(action==='detail'){if(selectionMode){if(selectedGames.has(id))selectedGames.delete(id);else selectedGames.add(id);renderContent();}else detail(id);}
  else if(action==='batch-mode'){selectionMode=!selectionMode;selectedGames.clear();renderContent();}
  else if(action==='batch-select-all'){for(const g of filtered())selectedGames.add(g.id);renderContent();}
  else if(action==='batch-clear'){selectedGames.clear();renderContent();}
  else if(action==='batch-apply'){if(!selectedGames.size){toast('先选择要标记的游戏');return;}const status=$('#batch-status').value;const count=await run(()=>api.bulkStatus([...selectedGames],status));if(count){toast(`已将 ${count} 部游戏标记为「${statuses[status]}」`);selectionMode=false;selectedGames.clear();await refresh();}}
  else if(action==='close-overlay')closeOverlay();
  else if(action==='favorite'){await run(()=>api.updateGame(id,{favorite:!g.favorite}));await refresh();}
  else if(action==='complete'){await run(()=>api.updateGame(id,{status:g.status==='completed'?'unplayed':'completed'}),g.status==='completed'?'已取消通关标记':'已标记为通关');await refresh();}
  else if(action==='launch'){if(g.confidence==='review'&&!g.manualLaunch){detail(id);editing=true;renderDrawer();toast('请先确认启动程序，保存后即可开始游玩');return;}b.disabled=true;await run(()=>api.launch(id),'启动请求已发送，正在检测游戏窗口');await refresh();}
  else if(action==='pause'){await run(()=>api.pause(id));await refresh();}
  else if(action==='finish'){await run(()=>api.finish(id),'本次计时已保存');await refresh();}
  else if(action==='open-folder')await run(()=>api.openFolder(id));
  else if(action==='edit'){editing=true;selectedId=id;renderDrawer();}
  else if(action==='cancel-edit'){editing=false;renderDrawer();}
  else if(action==='choose-exe'){const value=await run(()=>api.chooseExe(id,b.dataset.emulator==='true'));if(value){g[b.dataset.emulator==='true'?'emulatorPath':'launchPath']=value;const field=b.parentElement.querySelector('input');if(field)field.value=value;}}
  else if(action==='choose-cover'){await run(()=>api.chooseCover(id),'封面已更新');}
  else if(action==='hide-game'){await run(()=>api.updateGame(id,{hidden:true}),'条目已隐藏，可在设置中恢复');closeOverlay();await refresh();}
  else if(action==='match'){matchingId=id;matchQuery=g.metadata?.originalTitle||g.title;matchResults=null;matchWarnings=[];matchProvider='all';renderMatch();}
  else if(action==='close-match'){matchingId=null;renderDrawer();}
  else if(action==='apply-match'){b.disabled=true;const ok=await run(()=>api.applyMetadata(id,b.dataset.subject),'游戏资料已更新');if(ok){matchingId=null;await refresh();renderDrawer();}}
  else if(['bangumi','vndb','2dfan'].includes(action))await run(()=>api.openExternal(g.community[action==='2dfan'?'fan':action].url));
  else if(action==='bangumi-login')await run(()=>api.openExternal('https://next.bgm.tv/demo/access-token/create'));
  else if(action==='disconnect-bangumi'){await run(()=>api.setBangumiToken(''),'Bangumi 已断开连接');await refresh();}
  else if(action==='toggle-metadata'){await run(()=>api.updateSettings({autoMetadata:!data.settings.autoMetadata}));await refresh();}
  else if(action==='retry-metadata'){await run(()=>api.retryMetadata(),'已加入资料补全队列');}
  else if(action==='export')await run(()=>api.exportData(),'游戏库与记录已导出');
  else if(action==='data-folder')await run(()=>api.openData());
  else if(action==='restore-game'){await run(()=>api.updateGame(id,{hidden:false}),'已恢复显示');await refresh();}
  else if(action==='choose-locale'){await run(()=>api.chooseLocaleEmulator());await refresh();}
  else if(action==='manage-writers'){closeOverlay();managingWriters=true;writerSelection=new Set(data.settings.visibleWriters||[]);writerSearch='';renderWriterManager();}
  else if(action==='save-writers'){await run(()=>api.setWriterPreferences({showWriterFilters:data.settings.showWriterFilters!==false,visibleWriters:[...writerSelection]}),'脚本家名单已保存');closeOverlay();await refresh();}
  else if(action==='toggle-writers'){await run(()=>api.setWriterPreferences({showWriterFilters:data.settings.showWriterFilters===false,visibleWriters:data.settings.visibleWriters||[]}));await refresh();}
});
const composingSearches=new Set();
function handleSearchInput(input){if(input.id==='tag-query'){tagQuery=input.value;updateTagCatalog();return;}if(input.id==='writer-search'){writerSearch=input.value;updateWriterOptions();return;}if(input.id==='search'){query=input.value;if(view!=='library'){view='library';render();}else renderContent();}}
document.addEventListener('compositionstart',event=>{if(['writer-search','search','tag-query'].includes(event.target.id))composingSearches.add(event.target.id);});
document.addEventListener('compositionend',event=>{composingSearches.delete(event.target.id);handleSearchInput(event.target);});
document.addEventListener('input',event=>{if(event.isComposing||composingSearches.has(event.target.id))return;handleSearchInput(event.target);});
document.addEventListener('change',async event=>{const e=event.target;if(e.dataset.sidebarType){ensureSidebarDraft();const values=sidebarDraft[e.dataset.sidebarType];if(e.checked)values.add(e.dataset.sidebarValue);else values.delete(e.dataset.sidebarValue);const count=$('#sidebar-picked-count');if(count)count.textContent=sidebarSelectedCount();return;}if(e.dataset.writer){if(e.checked)writerSelection.add(e.dataset.writer);else writerSelection.delete(e.dataset.writer);const count=$('#writer-selected-count');if(count)count.textContent=writerSelection.size;return;}if(e.id==='detail-locale'){await run(()=>api.updateGame(e.dataset.id,{useLocaleEmulator:e.checked}));await refresh();return;}if(e.id==='sort'){sort=e.value;renderContent();}else if(e.id==='filter-mode'){filterMode=e.value;renderContent();}else if(e.id==='detail-status'){await run(()=>api.updateGame(e.dataset.id,{status:e.value}));await refresh();}else if(e.id==='candidate'){await run(()=>api.setCandidate(e.dataset.id,e.value));gameById(e.dataset.id).launchPath=e.value;const field=$('.exe-field input');if(field)field.value=e.value;}});
document.addEventListener('submit',async event=>{
  event.preventDefault();const form=event.target;
  if(form.id==='edit-form'){const f=new FormData(form),split=name=>String(f.get(name)||'').split(/[,，、;；\n]/).map(x=>x.trim()).filter(Boolean);const patch={customTitle:String(f.get('customTitle')).trim(),notes:String(f.get('notes')),userCompanies:split('userCompanies'),userWriters:split('userWriters'),userSeries:split('userSeries'),userTags:split('userTags'),bangumiUrl:String(f.get('bangumiUrl')).trim(),vndbUrl:String(f.get('vndbUrl')).trim(),fanUrl:String(f.get('fanUrl')).trim(),launchArgs:String(f.get('launchArgs')).split('\n').map(x=>x.trim()).filter(Boolean)};
    patch.autoSeries=f.has('autoSeries');patch.useLocaleEmulator=f.has('useLocaleEmulator');patch.showWriterTags=f.has('showWriterTags');
    patch.historicalSeconds=Math.max(0,Number(f.get('historyHours')||0)*3600+Number(f.get('historyMinutes')||0)*60);
    const g=gameById(form.dataset.id);const candidate=$('#candidate')?.value;if(candidate&&g.candidates.some(c=>c.path===candidate)){const result=await run(()=>api.setCandidate(g.id,candidate));if(result===undefined&&active(g.id))return;}
    const ok=await run(()=>api.updateGame(form.dataset.id,patch),'资料已保存');if(ok){editing=false;await refresh();renderDrawer();}
  }else if(form.id==='match-form'){matchQuery=$('#match-query').value.trim();if(!matchQuery)return;matchProvider=$('#match-provider').value;matchWarnings=[];matchResults='loading';renderMatch();const id=matchingId;const results=await run(()=>api.searchMetadata(id,matchQuery,matchProvider));if(matchingId!==id)return;matchResults=results?.items||[];matchWarnings=results?.warnings||[];renderMatch();}
  else if(form.id==='bangumi-token-form'){const input=form.elements.token,button=form.querySelector('button');button.disabled=true;const ok=await run(()=>api.setBangumiToken(input.value),'Bangumi 已连接，正在自动补全资料');button.disabled=false;if(ok){input.value='';input.blur();await refresh();}}
});
document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();$('#search')?.focus();}else if(e.key==='Escape'){if(matchingId){matchingId=null;renderDrawer();}else closeOverlay();}else if((e.key==='Enter'||e.key===' ')&&e.target.classList.contains('game-card')){e.preventDefault();e.target.click();}});
// Broken artwork falls back locally without leaving a broken image icon.
document.addEventListener('error',e=>{const img=e.target;if(img.tagName==='IMG'&&img.src.includes('/cover/')){const id=img.src.split('/cover/')[1]?.split('?')[0],g=gameById(id);if(g){const div=document.createElement('div');div.innerHTML=coverHTML({...g,customCover:null,localCover:null,metadata:{...g.metadata,cover:null}},img.className);img.replaceWith(div.firstElementChild);}}},true);
api.onChange(()=>refresh().catch(e=>toast(e.message)));api.onWarning(toast);
api.getLibrary().then(x=>{data=x;if(!x.settings.onboardingCompleted&&!x.settings.roots.length&&!x.games.length)view='setup';render();}).catch(e=>toast(e.message));
